sys_script.script:
// Workday Integration Test Script
// Run this in Scripts - Background to test the integration functionality

(function testWorkdayIntegration() {

    var utils = new x_58872_needit.WorkdayIntegrationUtils();

    gs.info("=== Starting Workday Integration Test ===");

    // Test 1: Validate Employee Data
    gs.info("Test 1: Data Validation");

    var validEmployee = {
        employee_id: "TEST001",
        email: "valid.test@company.com",
        first_name: "Valid",
        last_name: "Test"
    };

    var invalidEmployee = {
        employee_id: "",
        email: "invalid-email",
        first_name: "Invalid"
    };

    var validResult = utils.validateEmployeeData(validEmployee);
    var invalidResult = utils.validateEmployeeData(invalidEmployee);

    gs.info("Valid employee validation: " + validResult.isValid + " (errors: " + validResult.errors.length + ")");
    gs.info("Invalid employee validation: " + invalidResult.isValid + " (errors: " + invalidResult.errors.length + ")");

    if (invalidResult.errors.length > 0) {
        gs.info("Validation errors: " + invalidResult.errors.join(", "));
    }

    // Test 2: Username Generation
    gs.info("Test 2: Username Generation");

    var testCases = [
        { employee_id: "EMP001", email: "john.doe@company.com", first_name: "John", last_name: "Doe" },
        { employee_id: "EMP002", username: "custom.user", email: "custom@company.com" },
        { employee_id: "EMP003", email: "simple@company.com" }
    ];

    testCases.forEach(function(testCase, index) {
        var username = utils.generateUsername(testCase);
        gs.info("Username generation " + (index + 1) + ": " + username);
    });

    // Test 3: Department Creation (if it doesn't exist)
    gs.info("Test 3: Department Handling");

    var testDept = "Test Department - Workday Integration";
    var deptId = utils.findOrCreateDepartment(testDept);

    if (deptId) {
        gs.info("Department found/created with ID: " + deptId);

        // Clean up - delete the test department
        var cleanupDept = new GlideRecord('cmn_department');
        if (cleanupDept.get(deptId)) {
            cleanupDept.deleteRecord();
            gs.info("Cleaned up test department");
        }
    } else {
        gs.info("Failed to create test department");
    }

    // Test 4: API Endpoint URLs
    gs.info("Test 4: API Endpoint Information");

    var instanceName = gs.getProperty('instance_name');
    var baseUrl = "https://" + instanceName + ".service-now.com";
    var apiPath = "/api/x_58872_needit/workday_employee_integration";

    gs.info("Base API URL: " + baseUrl + apiPath);
    gs.info("Single employee endpoint: " + baseUrl + apiPath + "/employee");
    gs.info("Batch endpoint: " + baseUrl + apiPath + "/employees/batch");

    // Test 5: Sample JSON for testing
    gs.info("Test 5: Sample Request JSON");

    var sampleEmployee = {
        employee_id: "WD001234",
        username: "john.doe",
        email: "john.doe@company.com",
        first_name: "John",
        last_name: "Doe",
        title: "Software Engineer",
        department: "Information Technology",
        location: "New York Office",
        phone: "+1-555-123-4567",
        mobile_phone: "+1-555-987-6543",
        start_date: "2024-01-15",
        manager_employee_id: "WD005678"
    };

    gs.info("Sample employee JSON: " + JSON.stringify(sampleEmployee, null, 2));

    // Test 6: Curl Command Example
    gs.info("Test 6: Sample Curl Command");

    var curlCommand = "curl -X POST \\\n" +
                     "  '" + baseUrl + apiPath + "/employee' \\\n" +
                     "  -H 'Authorization: Basic <base64-encoded-credentials>' \\\n" +
                     "  -H 'Content-Type: application/json' \\\n" +
                     "  -d '" + JSON.stringify(sampleEmployee) + "'";

    gs.info("Sample curl command:\n" + curlCommand);

    gs.info("=== Workday Integration Test Complete ===");
    gs.info("Check the documentation file WORKDAY_INTEGRATION_GUIDE.md for complete usage instructions");

})();
